{
  "@context": {
    "odrl": "http://www.w3.org/ns/odrl/2/",
    "dct": "http://purl.org/dc/terms/",
    "xsd": "http://www.w3.org/2001/XMLSchema#",
    "schema": "https://schema.org/"
  },
  "@type": "odrl:Set",
  "@id": "https://dataspaces.es/policy/flamenco-heritage-subscription-v1",
  "dct:title": "Política de uso — Conservación del patrimonio del flamenco (suscripción mensual)",
  "dct:description": "Condiciones de acceso y uso para un recurso orientado a conservación, catalogación e investigación del patrimonio del flamenco. Modelo por suscripción mensual. Enfoque conservador: uso interno, no redistribución y obligaciones básicas de atribución y seguridad.",
  "odrl:target": "https://dataspaces.es/catalog/dataset/flamenco-heritage",
  "odrl:profile": "https://www.w3.org/ns/odrl/2/",
  "odrl:assigner": "did:web:provider.example.org",
  "odrl:assignee": "did:web:subscriber.example.org",
  "odrl:permission": [
    {
      "@type": "odrl:Permission",
      "odrl:target": "https://dataspaces.es/catalog/dataset/flamenco-heritage",
      "odrl:action": [
        { "@id": "odrl:read" },
        { "@id": "odrl:use" }
      ],
      "dct:description": "Lectura y uso interno del recurso mientras la suscripción esté activa.",
      "odrl:constraint": [
        {
          "@type": "odrl:Constraint",
          "odrl:leftOperand": { "@id": "odrl:purpose" },
          "odrl:operator": { "@id": "odrl:in" },
          "odrl:rightOperand": [
            "heritage-preservation",
            "cataloguing",
            "research",
            "education"
          ]
        }
      ],
      "odrl:duty": [
        {
          "@type": "odrl:Duty",
          "odrl:action": { "@id": "odrl:compensate" },
          "dct:description": "Pago por suscripción mensual para mantener el acceso.",
          "odrl:constraint": [
            {
              "@type": "odrl:Constraint",
              "odrl:leftOperand": { "@id": "odrl:payAmount" },
              "odrl:operator": { "@id": "odrl:eq" },
              "odrl:rightOperand": 49
            },
            {
              "@type": "odrl:Constraint",
              "odrl:leftOperand": { "@id": "odrl:payCurrency" },
              "odrl:operator": { "@id": "odrl:eq" },
              "odrl:rightOperand": "EUR"
            }
          ],
          "schema:billingDuration": "P1M"
        },
        {
          "@type": "odrl:Duty",
          "odrl:action": { "@id": "odrl:attribution" },
          "dct:description": "Obligatorio citar la fuente en publicaciones, informes y materiales educativos.",
          "odrl:constraint": [
            {
              "@type": "odrl:Constraint",
              "odrl:leftOperand": { "@id": "odrl:attribute" },
              "odrl:operator": { "@id": "odrl:eq" },
              "odrl:rightOperand": "Cita sugerida: 'Repositorio Patrimonio Flamenco (Proveedor TBD), versión/fecha de acceso TBD'."
            }
          ]
        },
        {
          "@type": "odrl:Duty",
          "odrl:action": { "@id": "odrl:secure" },
          "dct:description": "Medidas mínimas: cuentas nominales, no compartir credenciales, cifrado en reposo si se descarga, y control de acceso a copias locales."
        },
        {
          "@type": "odrl:Duty",
          "odrl:action": { "@id": "odrl:log" },
          "dct:description": "Conservar un registro básico de accesos/descargas para auditoría durante 90 días.",
          "odrl:constraint": [
            {
              "@type": "odrl:Constraint",
              "odrl:leftOperand": { "@id": "odrl:elapsedTime" },
              "odrl:operator": { "@id": "odrl:gteq" },
              "odrl:rightOperand": { "@value": "P90D", "@type": "xsd:duration" }
            }
          ]
        }
      ]
    },
    {
      "@type": "odrl:Permission",
      "odrl:target": "https://dataspaces.es/catalog/dataset/flamenco-heritage",
      "odrl:action": { "@id": "odrl:derive" },
      "dct:description": "Se permiten trabajos derivados (p. ej. análisis, índices, anotaciones) SOLO para uso interno y educativo.",
      "odrl:constraint": [
        {
          "@type": "odrl:Constraint",
          "odrl:leftOperand": { "@id": "odrl:purpose" },
          "odrl:operator": { "@id": "odrl:in" },
          "odrl:rightOperand": [
            "heritage-preservation",
            "cataloguing",
            "research",
            "education"
          ]
        }
      ],
      "odrl:duty": [
        {
          "@type": "odrl:Duty",
          "odrl:action": { "@id": "odrl:anonymize" },
          "dct:description": "Si el recurso incluye datos personales (p. ej. entrevistas), publicar derivados solo en formato anonimizado/agrupado cuando proceda."
        }
      ]
    }
  ],
  "odrl:prohibition": [
    {
      "@type": "odrl:Prohibition",
      "odrl:target": "https://dataspaces.es/catalog/dataset/flamenco-heritage",
      "odrl:action": { "@id": "odrl:distribute" },
      "dct:description": "Prohibida la redistribución del recurso o copias a terceros (incluye compartir ficheros, rehosting, o acceso a usuarios no suscritos)."
    },
    {
      "@type": "odrl:Prohibition",
      "odrl:target": "https://dataspaces.es/catalog/dataset/flamenco-heritage",
      "odrl:action": { "@id": "odrl:sell" },
      "dct:description": "Prohibida la reventa o sublicencia del recurso, total o parcial."
    },
    {
      "@type": "odrl:Prohibition",
      "odrl:target": "https://dataspaces.es/catalog/dataset/flamenco-heritage",
      "odrl:action": { "@id": "odrl:commercialize" },
      "dct:description": "Prohibido usar el recurso para explotación comercial directa (p. ej. producto/servicio basado en los contenidos) sin acuerdo específico con el proveedor."
    },
    {
      "@type": "odrl:Prohibition",
      "odrl:target": "https://dataspaces.es/catalog/dataset/flamenco-heritage",
      "odrl:action": { "@id": "odrl:use" },
      "odrl:constraint": [
        {
          "@type": "odrl:Constraint",
          "odrl:leftOperand": { "@id": "odrl:purpose" },
          "odrl:operator": { "@id": "odrl:eq" },
          "odrl:rightOperand": "advertising"
        }
      ],
      "dct:description": "Prohibido el uso para publicidad/segmentación."
    },
    {
      "@type": "odrl:Prohibition",
      "odrl:target": "https://dataspaces.es/catalog/dataset/flamenco-heritage",
      "odrl:action": { "@id": "odrl:use" },
      "odrl:constraint": [
        {
          "@type": "odrl:Constraint",
          "odrl:leftOperand": { "@id": "odrl:purpose" },
          "odrl:operator": { "@id": "odrl:eq" },
          "odrl:rightOperand": "training-ai-foundation-model"
        }
      ],
      "dct:description": "Prohibido usar el recurso para entrenar modelos de IA de propósito general (salvo acuerdo explícito)."
    }
  ],
  "odrl:obligation": [
    {
      "@type": "odrl:Duty",
      "odrl:action": { "@id": "odrl:delete" },
      "dct:description": "Al finalizar la suscripción, eliminar copias locales/descargas y conservar únicamente resultados agregados/anotaciones propias que no reproduzcan el contenido original."
    },
    {
      "@type": "odrl:Duty",
      "odrl:action": { "@id": "odrl:inform" },
      "dct:description": "Notificar incidentes de seguridad (filtración, acceso no autorizado) en un máximo de 72 horas.",
      "odrl:constraint": [
        {
          "@type": "odrl:Constraint",
          "odrl:leftOperand": { "@id": "odrl:recipient" },
          "odrl:operator": { "@id": "odrl:eq" },
          "odrl:rightOperand": "mailto:security@provider.example.org"
        }
      ]
    }
  ]
}

